  /**
   * ==========================================================================
   * 1. EXPORTACIÓN A EXCEL CON FÓRMULAS VIVAS
   * ==========================================================================
   */
  exportarSabanaExcel(datos: {
    docente: string; materia: string; grupo: string; periodo: string;
    columnas: { nombre: string, porcentaje: number }[];
    alumnos: {
      matricula: string; nombre: string; promedioAnterior: number | null;
      calificacionesRubros: (number | null)[];
      calificacionPeriodo: number; promedioFinal: number; observaciones?: string;
    }[];
  }) {
    const wb = XLSX.utils.book_new();

    // 1. Encabezados Informativos
    const infoRows = [
      ['COLEGIO VIZCAYA - SÁBANA DE CALIFICACIONES'],
      [''],
      ['DOCENTE:', datos.docente, '', 'MATERIA:', datos.materia],
      ['GRUPO:', datos.grupo, '', 'PERIODO:', datos.periodo],
      ['']
    ];

    // 2. Encabezados de Tabla
    const headers = ['NO.', 'MATRÍCULA', 'NOMBRE COMPLETO', 'PROM. ANT.'];
    datos.columnas.forEach(col => headers.push(`${col.nombre.toUpperCase()} (${col.porcentaje}%)`));
    headers.push('CALIF. PERIODO', 'PROM. FINAL', 'OBSERVACIONES');

    // 3. Datos con Fórmulas
    const dataRows: any[] = [];
    const startRow = infoRows.length + 1; // Fila donde inician los datos (base 0)

    datos.alumnos.forEach((al, i) => {
      const rowIndex = startRow + i + 1; // Índice fila Excel (base 1)
      const rowData: any[] = [
        i + 1,
        al.matricula,
        al.nombre,
        al.promedioAnterior ?? 0
      ];

      // Rubros
      al.calificacionesRubros.forEach(nota => {
        // Si es null, ponemos vacío pero numérico para fórmulas
        rowData.push({ t: 'n', v: nota ?? 0 });
      });

      // --- GENERACIÓN DE FÓRMULAS ---
      // Columnas: A=0, B=1, C=2, D=3 (PromAnt), E=4 (Inicio Rubros)
      const startColRubros = 4;
      let formulaSuma = '';

      // Fórmula Ponderada: =ROUND(E7*0.2 + F7*0.8, 1)
      datos.columnas.forEach((col, idx) => {
        const colLetter = XLSX.utils.encode_col(startColRubros + idx);
        const peso = col.porcentaje / 100;
        formulaSuma += `${colLetter}${rowIndex}*${peso}+`;
      });
      formulaSuma = formulaSuma.slice(0, -1); // Quitar último '+'

      // Fórmula Promedio Final: =IF(D7>0, ROUND((D7+CalifPer)/2, 1), CalifPer)
      const colPeriodoLetter = XLSX.utils.encode_col(startColRubros + datos.columnas.length);
      const colPromAntLetter = 'D';
      
      const formulaFinal = `ROUND(IF(${colPromAntLetter}${rowIndex}>0, (${colPromAntLetter}${rowIndex}+${colPeriodoLetter}${rowIndex})/2, ${colPeriodoLetter}${rowIndex}), 1)`;

      // Agregar celdas calculadas
      rowData.push({ t: 'n', f: `ROUND(${formulaSuma}, 1)` }); // Calif Periodo
      rowData.push({ t: 'n', f: formulaFinal });               // Promedio Final
      rowData.push(al.observaciones || '');

      dataRows.push(rowData);
    });

    const ws = XLSX.utils.aoa_to_sheet([...infoRows, headers, ...dataRows]);

    // Anchos
    const wscols = [
      { wch: 5 }, { wch: 15 }, { wch: 40 }, { wch: 10 },
      ...datos.columnas.map(() => ({ wch: 12 })),
      { wch: 15 }, { wch: 15 }, { wch: 30 }
    ];
    ws['!cols'] = wscols;

    XLSX.utils.book_append_sheet(wb, ws, 'Calificaciones');
    XLSX.writeFile(wb, `Sabana_${datos.materia.replace(/\s/g, '')}_${datos.grupo}.xlsx`);
  }

